#include <cstdio>
#include <cstdlib>
#include "engine/gameplay/borg_stats_edit_scene.hpp"
#include "tests/unit/editor_review_corrections_fixture.hpp"
namespace {using namespace gf;using namespace editor_review_corrections_fixture;unsigned checks=0;void check(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"inline stats edit: %s\n",why);std::abort();}}
bool open(Fixture& f,ForceEditorSession& s,bool cheat=true){return f.load()&&f.store.load(f.catalog,&f.owner)==ForceInventoryLoad::Missing&&s.open(f.owner,f.names,f.store,19)&&s.configure_tools({true,cheat},f.data)&&s.configure_preview_specification(f.data);}
bool stats(ForceEditorSession& s){return s.step({0,-1},0,0x100)&&s.held()==0&&s.step({},0,0x400)&&s.begin_provisional_borg_editor();}
void select(ForceEditorSession& s,unsigned field){for(unsigned i=0;s.borg_editor()->cursor()!=field&&i<10;++i)check(s.step_borg_editor(4,0,0),"Up/Down selects next element");check(s.borg_editor()->cursor()==field,"desired field owns input");}}
int main(){using namespace gf;using namespace editor_review_corrections_fixture;
    {Fixture f;ForceEditorSession s;check(open(f,s)&&stats(s),"actual held Box stats edit");const auto original=f.owner.state()->box[0].value;const auto revision=f.owner.revision();const auto profile=f.owner.state()->profile;const auto cost=f.owner.state()->forces[0].cost;check(s.borg_editor()->cursor()==1&&!s.borg_editor()->dirty(),"starts with native Cost element");
        for(unsigned field=0;field<10;++field){select(s,field);check(s.step_borg_editor(2,0,0),"Right adjusts selected draft field");check(f.owner.revision()==revision&&f.owner.state()->box[0].value==original&&f.owner.state()->profile==profile&&f.owner.state()->forces[0].cost==cost,"preview never mutates inventory/costs/collection/provenance");}
        ForceSpecificationSnapshot preview;check(s.borg_editor()->snapshot(f.owner,&preview)&&preview.value(f.owner)->variant==1&&preview.view(f.owner)->cost==111&&preview.view(f.owner)->level==2&&preview.view(f.owner)->hp==101,"same-menu displayed preview uses draft variant/cost/level/HP");check(!s.borg_editor()->committed_modified(f.owner)&&s.borg_editor()->dirty(),"draft does not display committed E marker");
        check(s.step_borg_editor(0,0x100,0)&&s.view()==ForceEditorView::Spec&&f.owner.revision()==revision+1&&s.held()==0,"A commits all ten fields in one revision and retains held instance");const auto& saved=f.owner.state()->box[0].value;check(saved.edits.modified&&saved.acquired==original.acquired&&saved.edits.values[6]==1&&saved.edits.values[7]==1&&f.owner.state()->box[1].value.edits==BorgEdits{},"committed marker/provenance and ammo retained; neighbor unchanged");check(f.owner.state()->forces[0].cost==111&&f.save.writes[0]==0,"shared force costs refresh once; disk save remains editor Start");check(s.step({},0,0x200)&&s.view()==ForceEditorView::Grid&&s.held()==0&&s.grid().current(f.owner),"stats back returns same held Box owner");}
    {Fixture f;ForceEditorSession s;check(open(f,s)&&stats(s),"fresh cancel fixture");const auto original=f.owner.state()->box[0].value;const auto revision=f.owner.revision();check(s.step_borg_editor(2,0,0)&&s.borg_editor()->dirty()&&s.step_borg_editor(0,0x200,0)&&f.owner.state()->box[0].value==original&&!original.edits.modified&&f.owner.revision()==revision,"B discards draft and leaves previously unedited flag false");check(s.begin_provisional_borg_editor()&&s.step_borg_editor(2,0,0)&&s.step_borg_editor(0,0x300,0)&&f.owner.state()->box[0].value==original,"B wins simultaneous A/B and never commits");}
    {Fixture f;ForceEditorSession s;check(open(f,s)&&f.owner.edit_borg({true,true},false,0,f.owner.revision(),BorgEditField::Cost,125)==ForceChange::Applied&&s.open(f.owner,f.names,f.store,19)&&s.configure_tools({true,true},f.data)&&stats(s),"previously committed edited Borg fixture");const auto before=f.owner.state()->box[0].value;const auto revision=f.owner.revision();check(s.borg_editor()->committed_modified(f.owner)&&s.step_borg_editor(2,0,0)&&s.step_borg_editor(0,0x200,0)&&f.owner.state()->box[0].value==before&&f.owner.revision()==revision&&before.edits.modified,"cancel preserves prior saved values and E marker");}
    {Fixture f;ForceEditorSession s;check(open(f,s)&&stats(s),"no-op fixture");const auto before=f.owner.state()->box[0].value;const auto revision=f.owner.revision();check(s.step_borg_editor(2,0,0)&&s.step_borg_editor(1,0,0)&&!s.borg_editor()->dirty()&&s.step_borg_editor(0,0x100,0)&&f.owner.state()->box[0].value==before&&f.owner.revision()==revision,"Right then Left restores default representation; A no-op has no flag/revision change");check(s.begin_provisional_borg_editor()&&s.step_borg_editor(0,0,1)&&!s.borg_editor()->dirty(),"obsolete plus/minus parameter no longer owns values");}
    {Fixture f;ForceEditorSession s;check(open(f,s)&&stats(s)&&s.step_borg_editor(2,0,0),"stale draft fixture");check(f.owner.rename_force(0,"OTHER")==ForceChange::Applied&&!s.borg_editor()&&!s.step_borg_editor(0,0x100,0)&&!s.step_borg_editor(0,0x200,0)&&!f.owner.state()->box[0].value.edits.modified,"external revision invalidates draft; commit/cancel cannot overwrite peer work");}
    {Fixture f;ForceEditorSession s;check(open(f,s,false)&&s.step({0,-1},0,0x400)&&!s.begin_provisional_borg_editor(),"cheat gate unchanged");}
    {Fixture f;ForceEditorSession s;check(open(f,s)&&f.owner.acquire(force_inventory_fixture::borg())==ForceChange::Applied&&f.owner.to_warehouse(3)==ForceChange::Applied&&s.open(f.owner,f.names,f.store,19)&&s.configure_tools({true,true},f.data)&&s.step({},0,0x20)&&s.step({},0,0x800)&&s.step({},0,0x400)&&s.begin_provisional_borg_editor(),"actual Warehouse stats context");const auto before=f.owner.state()->warehouse[0];const auto revision=f.owner.revision();check(s.step_borg_editor(2,0,0)&&s.step_borg_editor(0,0x200,0)&&f.owner.state()->warehouse[0]==before&&f.owner.revision()==revision,"Warehouse cancel is read-only");check(s.begin_provisional_borg_editor()&&s.step_borg_editor(2,0,0)&&s.step_borg_editor(0,0x100,0)&&s.step({},0,0x200)&&s.list().selected()==0&&s.list().current(f.owner)&&f.owner.state()->warehouse[0].edits.modified,"Warehouse A commit retains selected actual slot on return");}
    std::printf("inline stats staged A-save/B-cancel: %u checks PASS\n",checks);return 0;
}
